              "before": "  signal=options.signal;return new Promise((resolve,reject)=>signal.addEventListener('abort',()=>reject(new DOMException('Cancelled','AbortError')),{once:true}));\n });await client.signIn('owner@example.test','pw');const abort=new AbortController(),pending=client.contributions(workspace,'old',false,0,abort.signal);const check=assert.rejects(pending,{name:'AbortError'});abort.abort();await check;assert.equal(signal.aborted,true);assert.equal(client.userId,user);client.dispose();\n});\n",
              "after": "  signal=options.signal;return new Promise((resolve,reject)=>signal.addEventListener('abort',()=>reject(new DOMException('Cancelled','AbortError')),{once:true}));\n });await client.signIn('owner@example.test','pw');const abort=new AbortController(),pending=client.contributions(workspace,'old',false,0,abort.signal);const check=assert.rejects(pending,{name:'AbortError'});abort.abort();await check;assert.equal(signal.aborted,true);assert.equal(client.userId,user);client.dispose();\n});\n\ntest('content edits whitelist editable fields and use the original exact revision',async()=>{\n const x=setup([session,[{id:record}]]);await x.client.signIn('owner@example.test','pw');const version='2026-11-03T07:09:55.064432+00:00';\n await x.client.editContribution(workspace,record,{category:'Inspection',status:'completed',note:'Updated description',resolutionNote:'Follow-up',author_id:'forged',lon:0,risk_label:'low'},version);\n assert.deepEqual(JSON.parse(x.calls[1].options.body),{category:'Inspection',status:'completed',note_text:'Updated description',resolution_note:'Follow-up'});assert.equal(new URL(x.calls[1].url).searchParams.get('updated_at'),'eq.'+version);\n});\ntest('stale or revoked content edits fail without retrying or broadening the update',async()=>{const x=setup([session,[]]);await x.client.signIn('owner@example.test','pw');await assert.rejects(x.client.editContribution(workspace,record,{category:'Inspection',status:'open',note:'Draft',resolutionNote:''},'2026-01-01T00:00:00Z'),/record changed or access/);assert.equal(x.calls.length,2);});\ntest('invalid edit lengths and revisions are rejected before sending content',async()=>{const x=setup([session]);await x.client.signIn('owner@example.test','pw');for(const [values,revision] of [[{category:'Inspection',status:'open',note:'x'.repeat(8001),resolutionNote:''},'2026-01-01'],[{category:'Inspection',status:'open',note:'Draft',resolutionNote:''},'bad & filters']])await assert.rejects(x.client.editContribution(workspace,record,values,revision),/Invalid contribution edit/);assert.equal(x.calls.length,1);});\n"
